  "code": "\"\"\"\nCatalogPage - Page Object Model\n\nPage Object representing a single page in the application.\nProvides atomic UI interactions via WebInterface composition.\n\"\"\"\n\nfrom selenium.webdriver.common.by import By\nfrom interfaces.web_interface import WebInterface\n\n\nclass CatalogPage:\n    \"\"\"\n    Page Object for Catalog Page.\n\n    - NO decorators\n    - Locators as class constants\n    - Atomic methods (one UI action)\n    - Return self for chaining\n    - State-check methods for assertions\n    \"\"\"\n\n    def __init__(self, web: WebInterface):\n        \"\"\"Compose WebInterface - NO inheritance.\"\"\"\n        self.web = web\n\n    # ==================== LOCATORS (Class Constants) ====================\n    PRODUCT_CONTAINER = (By.CSS_SELECTOR, \".product-container\")\n    PRODUCT_NAME_LINK = (By.CSS_SELECTOR, \"a.product-name\")\n    ADD_TO_CART_BTN = (By.CSS_SELECTOR, \"a.ajax_add_to_cart_button\")\n    CONTINUE_SHOPPING_BTN = (By.CSS_SELECTOR, \"span.continue\")\n    PROCEED_CHECKOUT_BTN = (By.CSS_SELECTOR, \"a[title='Proceed to checkout']\")\n    LAYER_CART_MODAL = (By.CSS_SELECTOR, \"#layer_cart\")\n    WOMEN_CATEGORY = (By.CSS_SELECTOR, \"a[title='Women']\")\n\n    # ==================== ATOMIC METHODS (One UI Action) ====================\n\n    def click_product_name_link(self) -> \"CatalogPage\":\n        \"\"\"Click product name link link.\"\"\"\n        self.web.click(*self.PRODUCT_NAME_LINK)\n        return self\n\n    def click_add_to_cart_btn(self) -> \"CatalogPage\":\n        \"\"\"Click add to cart btn button.\"\"\"\n        self.web.click(*self.ADD_TO_CART_BTN)\n        return self\n\n    def click_continue_shopping_btn(self) -> \"CatalogPage\":\n        \"\"\"Click continue shopping btn button.\"\"\"\n        self.web.click(*self.CONTINUE_SHOPPING_BTN)\n        return self\n\n    def click_proceed_checkout_btn(self) -> \"CatalogPage\":\n        \"\"\"Click proceed checkout btn link.\"\"\"\n        self.web.click(*self.PROCEED_CHECKOUT_BTN)\n        return self\n\n    def click_women_category(self) -> \"CatalogPage\":\n        \"\"\"Click women category link.\"\"\"\n        self.web.click(*self.WOMEN_CATEGORY)\n        return self\n\n    # ==================== STATE-CHECK METHODS (For Assertions) ====================\n\n    def is_page_loaded(self) -> bool:\n        \"\"\"Check if product list page is loaded.\"\"\"\n        product_list_locator = (By.CSS_SELECTOR, \"ul.product_list\")\n        return self.web.is_element_displayed(*product_list_locator, timeout=10)\n\n    def has_products(self) -> bool:\n        \"\"\"Check if any products are displayed.\"\"\"\n        return self.get_product_count() > 0\n\n    def get_product_count(self) -> int:\n        \"\"\"Get number of products displayed.\"\"\"\n        product_items_locator = (By.CSS_SELECTOR, \"ul.product_list li.ajax_block_product\")\n        products = self.web.find_elements(*product_items_locator)\n        return len(products)\n\n    def get_product_names(self) -> list:\n        \"\"\"Get all product names on the page.\"\"\"\n        product_items_locator = (By.CSS_SELECTOR, \"ul.product_list li.ajax_block_product\")\n        product_name_locator = (By.CSS_SELECTOR, \".product-name\")\n        products = self.web.find_elements(*product_items_locator)\n        names = []\n        for product in products:\n            name_elem = product.find_element(*product_name_locator)\n            names.append(name_elem.text.strip())\n        return names\n",
