  "code": "\"\"\"\nCartPage - Page Object Model\n\nPage Object representing a single page in the application.\nProvides atomic UI interactions via WebInterface composition.\n\"\"\"\n\nfrom selenium.webdriver.common.by import By\nfrom interfaces.web_interface import WebInterface\n\n\nclass CartPage:\n    \"\"\"\n    Page Object for Cart Page.\n\n    - NO decorators\n    - Locators as class constants\n    - Atomic methods (one UI action)\n    - Return self for chaining\n    - State-check methods for assertions\n    \"\"\"\n\n    def __init__(self, web: WebInterface):\n        \"\"\"Compose WebInterface - NO inheritance.\"\"\"\n        self.web = web\n\n    # ==================== LOCATORS (Class Constants) ====================\n    CART_SUMMARY_TABLE = (By.CSS_SELECTOR, \"#cart_summary\")\n    CART_QUANTITY_INPUT = (By.CSS_SELECTOR, \"input.cart_quantity_input\")\n    DELETE_ITEM_LINK = (By.CSS_SELECTOR, \"a.cart_quantity_delete\")\n    PROCEED_TO_CHECKOUT_BUTTON = (By.CSS_SELECTOR, \"a.standard-checkout\")\n    TOTAL_PRICE = (By.CSS_SELECTOR, \"#total_price\")\n    EMPTY_CART_WARNING = (By.CSS_SELECTOR, \"p.alert-warning\")\n\n    # ==================== ATOMIC METHODS (One UI Action) ====================\n\n    def enter_cart_quantity_input(self, text: str) -> \"CartPage\":\n        \"\"\"Enter cart quantity input.\"\"\"\n        self.web.type_text(*self.CART_QUANTITY_INPUT, text=text)\n        return self  # Fluent API\n\n    def click_delete_item_link(self) -> \"CartPage\":\n        \"\"\"Click delete item link link.\"\"\"\n        self.web.click(*self.DELETE_ITEM_LINK)\n        return self\n\n    def click_proceed_to_checkout_button(self) -> \"CartPage\":\n        \"\"\"Click proceed to checkout button link.\"\"\"\n        self.web.click(*self.PROCEED_TO_CHECKOUT_BUTTON)\n        return self\n\n    # ==================== STATE-CHECK METHODS (For Assertions) ====================\n\n    def is_page_loaded(self) -> bool:\n        \"\"\"Check if cart page is loaded.\"\"\"\n        cart_summary_locator = (By.CSS_SELECTOR, \"#cart_summary\")\n        return self.web.is_element_displayed(*cart_summary_locator, timeout=10)\n\n    def has_items(self) -> bool:\n        \"\"\"Check if cart has items.\"\"\"\n        return self.get_item_count() > 0\n\n    def get_item_count(self) -> int:\n        \"\"\"Get number of items in cart.\"\"\"\n        cart_items_locator = (By.CSS_SELECTOR, \"#cart_summary tbody tr\")\n        items = self.web.find_elements(*cart_items_locator)\n        return len(items)\n\n    def is_cart_empty(self) -> bool:\n        \"\"\"Check if cart is empty.\"\"\"\n        return self.get_item_count() == 0\n",
